choose.when:
(

        e.created_by = #{scope.userId}
        OR e.primary_responsible_user_id = #{scope.userId}
        OR EXISTS (
            SELECT 1
            FROM equipment_responsible_person scoped_person
            WHERE scoped_person.tenant_id = e.tenant_id
              AND scoped_person.equipment_id = e.id
              AND scoped_person.user_id = #{scope.userId}
              AND scoped_person.status = 1
              AND scoped_person.deleted = 0
        )


        OR


        e.organization_id IN

            #{organizationId}


)

mapper.select:
SELECT COUNT(*)
FROM visualization_model_resource
WHERE tenant_id = #{tenantId}
  AND resource_code = #{resourceCode}
  AND deleted = 0
  AND id != #{excludeId}

SELECT id FROM visualization_model_resource
WHERE tenant_id = #{tenantId}
  AND resource_code = #{resourceCode}
  AND deleted = 0
LIMIT 1

SELECT COUNT(*) FROM visualization_scene_node
WHERE tenant_id = #{tenantId} AND scene_id = #{sceneId}
  AND node_code = #{nodeCode} AND deleted = 0
AND id != #{excludeId}
